//             if(!taskToUpdate) return;
//
//             const isDone = taskToUpdate.doneFlag;
//
//             if(isDone){
//                 await api.put(`/tasks/${id}/undone`);
//             }else{
//                 await api.post(`/tasks/${id}/done`);
//             }
//
//             setTasks((prevTasks) =>
//                 prevTasks.map((task) =>
//                     task.id === id ? { ...task, doneFlag: !task.doneFlag } : task
//                 )
//             );
//         }catch(error){
//             console.error("Error marking task as done", error);
//         }
//     };

    return (
        <div>
            <h1>To-Do App</h1>
            <TaskList tasks = {tasks} markTaskAsDone = {markTaskAsDone} onTaskAdded = {fetchTasks} onTaskUpdated = {fetchTasks} />
        </div>
    );
};

export default App;
